class CppMappedIterable : public CppIterable {
 private:
  CppIterable _source;
  std::function<Any()> _f;

 public:
  CppMappedIterable(CppIterable _source, std::function<Any()> _f) {}

  CppIterator iterator() { return CppMappedIterable(_source, _f); }

  Int length() { return _source; }
};

// ============================================================================
// 类: CppMappedIterator
// ============================================================================

class CppMappedIterator : public CppIterator {
 private:
  CppIterator _iterator;
  std::function<Any()> _f;
  Any _current = nullptr;

 public:
  CppMappedIterator(CppIterator _iterator, std::function<Any()> _f) {}

  Any current() { return _current; }

  Bool moveNext() {
    {
      if (_iterator.moveNext()) {
        _current = _f(_iterator.current());
        return dart_bool(true);
      }
      return dart_bool(false);
    }
  }
};

